const subjects = subjectData.map(([id, name, icon, tone, entries], index) => ({
  id, name, icon, tone, extra: index >= 7,
  topics: entries.map(([key, title, term, description, raw]) => ({
    key, title, term, description,
    questions: raw.trim().split('\n').map((line, i) => {
      const [prompt, correct, ...rest] = line.split('|');
      const explanation = rest.pop();
      const options = [correct, ...rest];
      const offset = (key.charCodeAt(0) + i) % options.length;
      return {
        id: key + '-' + (i + 1), subject: id, topic: key, prompt, correct, explanation,
        options: options.slice(offset).concat(options.slice(0, offset))
      };
    })
  }))
}));

const mathTopics = subjects.find(subject => subject.id === 'math').topics;
function addCalculation(topicKey, index, prompt, correct, explanation) {
  mathTopics.find(topic => topic.key === topicKey).questions.push({
    id: topicKey + '-calc-' + index, subject: 'math', topic: topicKey,
    prompt, correct: String(correct), explanation, options: null
  });
}
for (let n = 1; n <= 12; n++) {
  const a = n + 7;
  const b = n % 4 + 2;
  const x = n - 4;
  const c = n % 3 + 1;
  const result = b * x + c;
  const first = 24 + n * 2;
  const second = 32 + n;
  const y = n % 5 + 1;
  addCalculation('rational', n, '计算（−' + a + '）＋' + b + '×' + n + '。只填数字。', -a + b * n, '先算乘法，' + b + '×' + n + '＝' + (b * n) + '，再加上 −' + a + '。');
  addCalculation('equation', n, '解方程 ' + b + 'x＋' + c + '＝' + result + '。请填 x 的值。', x, '两边减去 ' + c + ' 得 ' + b + 'x＝' + (b * x) + '，再同时除以 ' + b + '。');
  addCalculation('parallel', n, '三角形的两个内角分别为 ' + first + '° 和 ' + second + '°，求第三个内角。只填数字。', 180 - first - second, '用 180° 减去已知两个内角的度数。');
  addCalculation('systems', n, '已知 x＋y＝' + (n + y) + '，x−y＝' + (n - y) + '。请填 x 的值。', n, '把两式相加，消去 y，得 2x＝' + (2 * n) + '，两边同时除以 2。');
}
